import Mathlib

noncomputable def nearestIntegerDistance (x : ℝ) : ℝ :=
  sInf { y : ℝ | ∃ k : ℤ, y = |x - (k : ℝ)| }

def feasible (r : ℕ) (C : ℝ) : Prop :=
  ∃ a : ℕ → ℝ,
    (∀ n : ℕ, 1 ≤ n → a (n + 1) = (r : ℝ) * a n) ∧
    (∀ n : ℕ, 1 ≤ n → nearestIntegerDistance (a n) ≥ C)

def answer (r : ℕ) : ℝ :=
  if r % 2 = 1 then (1 / 2 : ℝ)
  else (r : ℝ) / (2 * ((r : ℝ) + 1))

def originalStatement : Prop :=
  ∀ r : ℕ, 1 ≤ r →
    feasible r (answer r) ∧
    ∀ C : ℝ, feasible r C → C ≤ answer r

